<?php require_once __DIR__.'/components.php';$category=(string)($_GET['kategorie']??'');$search=substr(trim((string)($_GET['suche']??'')),0,150);$slug=(string)($_GET['artikel']??'');$entries=$slug?all('SELECT * FROM shop_faq WHERE slug=? AND published=1',[$slug]):published_faqs($category,$search);if($slug && !$entries)http_response_code(404); ?>
<section class="container compact-page faq-page"><div class="page-heading"><div class="eyebrow">WISSEN & HILFE</div><h1>Deine Fragen. Klare Antworten.</h1><p>Anleitungen für E-Mail, FTP, SSH und deine Produkte.</p></div><form method="get" class="faq-search"><label class="field"><span>In den Anleitungen suchen</span><input type="search" name="suche" maxlength="150" value="<?= e($search) ?>" placeholder="E-Mail einrichten, Dateien hochladen …"></label><button class="button button-outline">Suchen <?= icon('search') ?></button></form><div class="faq-filters"><a class="filter-chip <?= !$category?'active':'' ?>" href="/faq">Alle Themen</a><?php foreach(faq_categories() as $key=>$caption): ?><a class="filter-chip <?= $category===$key?'active':'' ?>" href="/faq?kategorie=<?= $key ?>"><?= e($caption) ?></a><?php endforeach ?></div>
<?php if(!$entries): ?><section class="panel"><?php empty_state('headset',$slug?'Anleitung nicht gefunden':($search?'Keine passende Anleitung gefunden':'Die Anleitungen werden gerade ergänzt.'),'Unser Support hilft dir bei der Einrichtung deiner Produkte.','/hilfe','Hilfe & Kontakt'); ?></section><?php else: ?><div class="faq-entries"><?php foreach($entries as $entry): ?><details class="panel faq-entry" <?= $slug?'open':'' ?>><summary><span><small><?= e(faq_categories()[$entry['category']]) ?></small><strong><?= e($entry['title']) ?></strong></span><?= icon('plus') ?></summary><div class="faq-answer"><p class="pre-wrap"><?= e($entry['body']) ?></p><?php foreach(json_decode($entry['links'],true) as $link): ?><p><a class="text-link" href="<?= e($link['url']) ?>" target="_blank" rel="noopener noreferrer"><?= e($link['label']) ?> <?= icon('external') ?></a></p><?php endforeach ?><a class="small text-link" href="/faq?artikel=<?= e($entry['slug']) ?>">Link zu dieser Anleitung <?= icon('arrow') ?></a></div></details><?php endforeach ?></div><?php endif ?><div class="info-box"><?= icon('headset') ?><span>Deine Frage ist noch offen? <a href="/konto/support">Erstelle ein Support-Ticket.</a></span></div></section>
